from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression
from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class SwActivation(OperationPrototype):
    def __init__(self, bts):
        super(SwActivation, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "SW activation",
            "Start point": "First cell down",
            "End point": "Last cell up",
            "Requirement": "-",
        }

    def get_kpi(self, inter_release=False):
        """
        Gets kpi for software activation operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software activation
        :rtype: dict
        """
        log_suppression("There was no configuration found in Gates tool for Your setup, "
                        "returning default timeout for software activation. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] = 2400
        return self.operation_details
